mapper.select:
SELECT a.id id, a.reade_value readeValue, a.now_reade_value nowReadeValue, a.now_reade_time nowReadeTime, a.last_reade_value lastReadeValue, a.reade_last_value readeLastValue, a.last_reade_time lastReadeTime, a.device_id deviceId, b.`code` code, b.device_name deviceName, b.device_area deviceArea FROM meter_reade_record a LEFT JOIN meter_device b ON a.device_id = b.device_id
a.last_reade_time is not null
and b.device_name like concat('%',#{param.keyword},'%')
and b.instrument_type = #{param.instrumentType}
and b.device_area_id like concat('%',#{param.deviceAreaId},'%')
and a.device_id in
#{item}
and a.now_reade_time between #{param.begin} and #{param.end}
order by a.now_reade_time DESC
